import{_ as l,o as s,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"CDS G/H (Day 2) - RGW: bucket index scalability","description":"","frontmatter":{"title":"CDS G/H (Day 2) - RGW: bucket index scalability","date":"2014-06-26T00:00:00.000Z","updated":"2014-06-26T00:00:00.000Z","tags":["Ceph","bucket index scalability","RGW","distributed storage","storage systems"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_G_H_Day_2_-_RGW_-_bucket_index_scalability.md","filePath":"posts/2014/CDS_G_H_Day_2_-_RGW_-_bucket_index_scalability.md","lastUpdated":1780459816000}'),e={name:"posts/2014/CDS_G_H_Day_2_-_RGW_-_bucket_index_scalability.md"};function r(_,t,n,a,p,g){return s(),i("div",null,[...t[0]||(t[0]=[o("<p><strong>会议纪要</strong></p><p><strong>会议主题</strong>： Ceph分布式存储系统中RGW（Red Hat Gluster Storage）的桶索引可扩展性问题讨论</p><p><strong>会议时间</strong>： 2014年6月26日</p><p><strong>参会人员</strong>： Duong（负责桶索引可扩展性的研发人员）、Federer（主持人）、Teddy（负责Ceph集群运维）、Josh、Yahoo（其他研发人员）</p><p><strong>会议内容</strong>：</p><p><strong>一、桶索引可扩展性问题</strong></p><ol><li><strong>问题概述</strong>： <ul><li>现有的桶索引实现存在可扩展性问题，主要体现在以下两方面： <ul><li>单个桶索引对象的处理能力有限，只能支持10-20 RPS的请求量。</li><li>随着记录数量的增加，桶索引对象存储的更新操作会占用大量时间，影响系统性能。</li></ul></li></ul></li><li><strong>解决方案</strong>： <ul><li><strong>方案一</strong>： 将桶索引对象进行分片，每个分片对应一个桶索引对象，从而提高处理能力。</li><li><strong>方案二</strong>： 禁用桶索引功能，适用于不需要桶索引列表功能的场景。</li><li><strong>方案三</strong>： 在创建桶时允许用户指定分片数量，并存储在桶元数据中。</li></ul></li></ol><p><strong>二、技术细节讨论</strong></p><ol><li><strong>分片存储</strong>： <ul><li>将桶索引对象进行分片可以提高处理能力，但会引入新的问题，如分片管理、元数据更新等。</li><li>讨论了分片策略、元数据存储、桶索引日志等细节。</li></ul></li><li><strong>无序列表操作</strong>： <ul><li>提出了一种新的无序列表操作，可以减少系统负载，但会牺牲列表的有序性。</li><li>讨论了无序列表的实现方式、性能影响等。</li></ul></li></ol><p><strong>三、行动计划</strong></p><ol><li>Duong将根据讨论结果修改原型，并提交相应的Pull Request。</li><li>其他研发人员将参与审查和改进Pull Request。</li><li>讨论未来可能的桶索引自动分片功能。</li></ol><p><strong>四、其他事项</strong></p><ol><li>讨论了多部分上传的原子性问题，认为目前实现方式是安全的。</li><li>讨论了桶索引与桶索引日志的存储方式，认为应该将它们存储在同一个对象中。</li></ol><p><strong>五、会议总结</strong></p><p>本次会议针对Ceph分布式存储系统中RGW的桶索引可扩展性问题进行了深入讨论，并提出了相应的解决方案。后续将根据讨论结果进行技术实现和改进。</p>",15)])])}const c=l(e,[["render",r]]);export{d as __pageData,c as default};
